#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1000000007;

int add_mod(int x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
    return x;
}

long long mul_mod(long long x, long long y) {
    return (x * y) % MOD;
}

template<size_t ROWS, size_t COLS>
struct Matrix {
    int m[ROWS][COLS];

    void zero() {
        memset(m, 0, sizeof(m));
    }

    void unit() {
        zero();
        for (size_t i = 0; i < min(ROWS, COLS); ++i) m[i][i] = 1;
    }

    template<size_t K>
    static Matrix<ROWS, COLS> mul(const Matrix<ROWS, K>& a, const Matrix<K, COLS>& b) {
        Matrix<ROWS, COLS> res;
        res.zero();
        for (size_t i = 0; i < ROWS; ++i)
            for (size_t j = 0; j < K; ++j)
                if (a.m[i][j])
                    for (size_t k = 0; k < COLS; ++k)
                        res.m[i][k] = add_mod(res.m[i][k], (int)mul_mod(a.m[i][j], b.m[j][k]));
        return res;
    }

    Matrix<ROWS, COLS> operator+(const Matrix<ROWS, COLS>& other) const {
        Matrix<ROWS, COLS> res;
        for (size_t i = 0; i < ROWS; ++i)
            for (size_t j = 0; j < COLS; ++j)
                res.m[i][j] = add_mod(m[i][j], other.m[i][j]);
        return res;
    }

    Matrix<ROWS, COLS> operator*(int scalar) const {
        Matrix<ROWS, COLS> res = *this;
        for (size_t i = 0; i < ROWS; ++i)
            for (size_t j = 0; j < COLS; ++j)
                res.m[i][j] = (int)mul_mod(res.m[i][j], scalar);
        return res;
    }

    int* operator[](size_t idx) { return m[idx]; }
    const int* operator[](size_t idx) const { return m[idx]; }
};

using ll = long long;

ll n;
int K;
vector<int> digits;
Matrix<35, 35> A[65][35], S[65][35], P[65][35], result;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> K;

    for (int i = 0; i < K; ++i) {
        A[0][i].unit();
        for (int j = 0; j <= K; ++j) A[0][i][i][j] = 1;
    }

    ll block_len = K;
    for (int level = 1; block_len <= n; ++level, block_len *= K) {
        S[level - 1][K - 1] = A[level - 1][K - 1];
        for (int j = K - 2; j >= 0; --j)
            S[level - 1][j] = Matrix<35, 35>::mul(A[level - 1][j], S[level - 1][j + 1]);

        P[level - 1][0] = A[level - 1][0];
        for (int j = 1; j < K; ++j)
            P[level - 1][j] = Matrix<35, 35>::mul(P[level - 1][j - 1], A[level - 1][j]);

        A[level][0] = S[level - 1][0];
        for (int j = 1; j < K; ++j)
            A[level][j] = Matrix<35, 35>::mul(S[level - 1][j], P[level - 1][j - 1]);
    }

    while (n) {
        digits.push_back(n % K);
        n /= K;
    }

    int offset = 0;
    result.unit();
    for (int i = (int)digits.size() - 1; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j)
            result = Matrix<35, 35>::mul(result, A[i][(j + offset) % K]);
        offset = (offset + digits[i]) % K;
    }

    int answer = 1;
    for (int i = 0; i < K; ++i)
        answer = add_mod(answer, result[i][K]);
    cout << answer << '\n';

    return 0;
}
